import{_ as i,o as a,c as s,a2 as n}from"./chunks/framework.7w-lhQN6.js";const m=JSON.parse('{"title":"Gemini CLI","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/gemini-cli.md","filePath":"ko/guide/gemini-cli.md","lastUpdated":1793550481000}'),t={name:"ko/guide/gemini-cli.md"};function o(l,e,d,c,p,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="gemini-cli" tabindex="-1">Gemini CLI <a class="header-anchor" href="#gemini-cli" aria-label="Permalink to &quot;Gemini CLI&quot;">​</a></h1><p>이 문서를 끝내면 Gemini CLI에 MCP Lens 확장이 설치되어, Gemini CLI 세션의 모든 MCP 툴 호출이 로컬에 기록되고 Gemini CLI로 쓰는 서버들에 대해 <code>mcp-lens report</code>의 <code>calls</code> 열이 더 이상 0에 머물지 않는다.</p><h2 id="쉬운-방법-vs-code-확장이-대신-하게-한다" tabindex="-1">쉬운 방법: VS Code 확장이 대신 하게 한다 <a class="header-anchor" href="#쉬운-방법-vs-code-확장이-대신-하게-한다" aria-label="Permalink to &quot;쉬운 방법: VS Code 확장이 대신 하게 한다&quot;">​</a></h2><p>VS Code 확장을 쓰고 있다면 <code>MCP Lens: Install Hooks for All Clients</code> 커맨드를 실행한다. 그러면 이 확장이 자동으로 설치된다. <a href="/MCPLens/ko/guide/vscode-extension">VS Code 확장</a> 참고. 이 경로를 탔다면 아래 수동 설치 절은 건너뛰고 <a href="#설치-후">설치 후</a>로 바로 간다. 확장이 어떤 경로로 설치됐든 이 절은 그대로 적용된다.</p><h2 id="확장을-수동으로-설치한다" tabindex="-1">확장을 수동으로 설치한다 <a class="header-anchor" href="#확장을-수동으로-설치한다" aria-label="Permalink to &quot;확장을 수동으로 설치한다&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extensions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /absolute/path/to/packages/gemini-extension</span></span></code></pre></div><p><code>/absolute/path/to</code> 자리에 자기 저장소 클론의 절대 경로를 넣는다. 확장의 매니페스트 이름은 <code>mcp-lens</code>이므로, 설치 후 <code>gemini extensions list</code>를 실행하면 설치된 확장 목록에 <code>mcp-lens</code>가 보인다. 이후 Gemini CLI를 재시작해 확장과 훅 등록을 불러오게 한다.</p><h2 id="수집하는-것" tabindex="-1">수집하는 것 <a class="header-anchor" href="#수집하는-것" aria-label="Permalink to &quot;수집하는 것&quot;">​</a></h2><p>확장은 Gemini CLI 훅 이벤트에서 로컬 전용 MCP 회계 메타데이터만 수집하고, <code>tool_input</code>, <code>tool_response</code>, <code>llmContent</code>, <code>returnDisplay</code>를 포함한 민감한 페이로드 필드는 버린다. 번들된 훅 러너만 쓰며 런타임을 내려받지 않고 MCP Lens 데이터베이스나 네트워크도 절대 열지 않는다. 이벤트는 <code>~/.mcplens/inbox</code>에 원자적으로 큐잉되고, Gemini의 원본 로그는 수정되거나 이동되지 않는다.</p><h2 id="설치-후" tabindex="-1">설치 후 <a class="header-anchor" href="#설치-후" aria-label="Permalink to &quot;설치 후&quot;">​</a></h2><p>Gemini CLI를 재시작해 확장과 훅을 불러온다.</p><p>확장을 지우지 않고 수집만 멈추려면 비활성화하고 다시 재시작한다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gemini</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> extensions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp-lens</span></span></code></pre></div><p>이 명령은 확장을 삭제하지 않고 새 캡처만 멈춘다. 확장 상태를 바꾼 뒤에는 Gemini CLI를 재시작해야 변경이 적용된다.</p><p>완전히 제거하려면 Gemini CLI의 확장 제거 명령으로 삭제하고 재시작한다. 어느 쪽이든 이미 큐에 쌓인 메타데이터나 원본 Gemini 로그에는 손대지 않는다.</p>',15)])])}const k=i(t,[["render",o]]);export{m as __pageData,k as default};
